import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import AuthModal from './AuthModal';
import UserMenu from './UserMenu';

function Navbar() {
  const { user, isLoggedIn } = useAuth();
  const [showAuthModal, setShowAuthModal] = useState(false);
  const navigate = useNavigate();

  return (
    <>
      <nav className="sticky top-0 z-50 glass-morphism px-6 py-4 flex justify-between items-center">
        <div className="flex items-center space-x-3 cursor-pointer" onClick={() => navigate('/')}>
          <div className="w-10 h-10 bg-[#004b93] rounded-lg flex items-center justify-center text-white">
            <i className="fas fa-newspaper text-xl"></i>
          </div>
          <h1 className="text-xl font-extrabold tracking-tight text-[#004b93]">
            대진대학교 신문사
          </h1>
        </div>

        <div className="hidden md:flex space-x-8 font-semibold text-gray-600">
          <a href="#" className="hover:text-[#004b93] transition">대학뉴스</a>
          <a href="#" className="hover:text-[#004b93] transition">학술/문화</a>
          <a href="#" className="hover:text-[#004b93] transition">오피니언</a>
          <a href="#" className="hover:text-[#004b93] transition">학생자치</a>
        </div>

        <div className="flex items-center space-x-4">
          <button className="p-2 text-gray-500 hover:bg-gray-100 rounded-full transition">
            <i className="fas fa-search"></i>
          </button>

          {isLoggedIn ? (
            <UserMenu />
          ) : (
            <button
              onClick={() => setShowAuthModal(true)}
              className="bg-[#004b93] text-white px-4 py-2 rounded-full text-sm font-bold hover:bg-[#003a75] transition"
            >
              로그인
            </button>
          )}
        </div>
      </nav>

      {showAuthModal && <AuthModal onClose={() => setShowAuthModal(false)} />}
    </>
  );
}

export default Navbar;
